#[AsMessageHandler]
final readonly class SendOrderEmailHandler
{
    public function __construct(
        private OrderRepository $orders,
        private MailerInterface $mailer,
    ) {}

    public function __invoke(OrderPlaced $event): void
    {
        $order = $this->orders->find($event->orderId);
        if (null === $order) {
            return; // the order is gone, nothing to do
        }

        $this->mailer->send((new TemplatedEmail())
            ->to($order->getCustomerEmail())
            ->subject('We received order #'.$order->getId())
            ->htmlTemplate('email/order_placed.html.twig')
            ->context(['order' => $order]));
    }
}

#[Route('/orders/{id}/pay', methods: ['POST'])]
#[IsGranted('PAY', subject: 'order')]
public function pay(
    Order $order,
    OrderService $orders,
    MessageBusInterface $bus,
): JsonResponse {
    $orders->markPaymentPending($order);                // state: pending, with flush
    $bus->dispatch(new ChargeOrder($order->getId()));

    return $this->json(
        ['status' => 'pending', 'statusUrl' => '/orders/'.$order->getId()],
        Response::HTTP_ACCEPTED,                        // 202: received, work in progress
    );
}

