#[AsMessageHandler]
final readonly class ChargeOrderHandler
{
    public function __construct(
        private PaymentGateway $gateway,
        private OrderService $orders,
    ) {}

    public function __invoke(ChargeOrder $m): void
    {
        $result = $this->gateway->charge($m->orderId);   // slow, can fail
        $this->orders->settle($m->orderId, $result);     // pending becomes paid or failed
    }
}

public function credited(Account $account, int $amount): void
{
    $eventId = Uuid::v7()->toRfc4122();
    $this->bus->dispatch(
        new AccountCredited($eventId, $account->getId(), $amount),
        [
            // same account = same group = processed in order
            new AmazonSqsFifoStamp(
                messageGroupId: (string) $account->getId(),
                messageDeduplicationId: $eventId,
            ),
        ],
    );
}

#[AsMessageHandler]
final readonly class AccountCreditedHandler
{
    public function __construct(private Connection $db) {}

    public function __invoke(AccountCredited $m): void
    {
        $this->db->transactional(function () use ($m): void {
            $new = $this->db->executeStatement(
                'INSERT INTO applied_events (id) VALUES (?) ON CONFLICT DO NOTHING',
                [$m->eventId],
            );
            if ($new === 0) {
                return; // seen before: a redelivery, skip it
            }
            $this->db->executeStatement(
                'UPDATE accounts SET balance = balance + ? WHERE id = ?',
                [$m->amount, $m->accountId],
            );
        });
    }
}

#[AsMessageHandler]
final readonly class SendSmsHandler
{
    public function __construct(private TexterInterface $texter) {}

    public function __invoke(SendSms $m): void
    {
        if (!preg_match('/^\+1\d{10}$/', $m->phone)) {
            // permanent failure: retrying won't fix the number
            throw new UnrecoverableMessageHandlingException('Invalid phone number');
        }

        // a gateway outage raises TransportException: temporary, so it retries
        $this->texter->send(new SmsMessage($m->phone, $m->text));
    }
}

public function __invoke(AwardPoints $m): void
{
    // on redelivery the same points are added again
    $this->db->executeStatement(
        'UPDATE loyalty SET points = points + ? WHERE user_id = ?',
        [$m->points, $m->userId],
    );
}

public function __invoke(AwardPoints $m): void
{
    $this->db->beginTransaction();
    try {
        $new = $this->db->executeStatement(
            'INSERT INTO processed_message (message_id, handler) VALUES (?, ?)
             ON CONFLICT DO NOTHING', [$m->messageId, self::class]);
        if (0 === $new) {            // already processed
            $this->db->rollBack();
            return;
        }
        $this->db->executeStatement(
            'UPDATE loyalty SET points = points + ? WHERE user_id = ?',
            [$m->points, $m->userId]);
        $this->db->commit();
    } catch (\Throwable $e) {
        $this->db->rollBack();
        throw $e;                    // rethrow so the retry happens
    }
}

