final readonly class MainSchedule implements ScheduleProviderInterface
{
    public function __construct(
        private CacheInterface $cache,
        private LockFactory $locks,
    ) {}

    public function getSchedule(): Schedule
    {
        return (new Schedule())
            ->add(RecurringMessage::cron(
                '0 2 * * *', new BuildDailyReport(), new \DateTimeZone('America/Phoenix'),
            ))
            ->add(RecurringMessage::every('5 minutes', new ReleaseStuckPayouts()))
            ->stateful($this->cache)
