public function __invoke(ExportUsers $m): void
{
    $ids = $this->db->fetchFirstColumn(
        'SELECT id FROM users WHERE id > ? ORDER BY id LIMIT 500',
        [$m->afterId],
    );
    if ([] === $ids) {
        $this->jobs->markDone($m->jobId);
        return;
    }
    $this->exporter->upsertChunk($m->jobId, $ids);   // safe even if a chunk runs twice
    $last = (int) end($ids);
    $this->jobs->saveCheckpoint($m->jobId, $last);
    $this->bus->dispatch(new ExportUsers($m->jobId, $last));
}

#[AsEventListener]
final readonly class JobFailureLogger
{
