#[AsMessageHandler]
final class SendInvoiceHandler
{
    private ?array $rates = null;

    public function __invoke(SendInvoice $m): void
    {
        $this->rates ??= $this->fx->loadRates();     // loaded once, kept for hours
        $path = '/var/www/app/var/invoices/'.$m->invoiceId.'.pdf';
        file_put_contents($path, $this->pdf->render($m->invoiceId, $this->rates));
        // the next worker may run on another server, where $path does not exist
        $this->bus->dispatch(new EmailInvoice($path));
    }
}

#[AsMessageHandler]
final readonly class SendInvoiceHandler
{
    public function __construct(
        private FilesystemOperator $invoicesStorage,  // flysystem on S3 or a shared disk
        private FxRates $fx,                          // cached with a 5-minute TTL
        private InvoicePdf $pdf,
        private MessageBusInterface $bus,
    ) {}

    public function __invoke(SendInvoice $m): void
    {
        $this->invoicesStorage->write(
            "invoices/{$m->invoiceId}.pdf",
            $this->pdf->render($m->invoiceId, $this->fx->current()),
        );
        $this->bus->dispatch(new EmailInvoice($m->invoiceId)); // the ID, not the path
    }
}

final readonly class OrderNotifier
{
    public function __construct(
        private NotifierInterface $notifier,
        private PreferenceRepository $prefs,
    ) {}

    public function shipped(Order $order): void
    {
        $user = $order->getUser();
        $channels = $this->prefs->enabledChannels($user, 'order_shipped'); // ['email','sms']
        if ([] === $channels) {
            return;                       // the user doesn't want it
        }

        $subject = 'Order #'.$order->getId().' has shipped';
        $notification = (new Notification($subject, $channels))
            ->content('The courier will arrive tomorrow.')
            ->importance(Notification::IMPORTANCE_HIGH);

        $recipient = new Recipient($user->getEmail(), $user->getPhone());
        $this->notifier->send($notification, $recipient);
    }
}

