enum NotificationKind: string
{
    case Otp = 'otp';
    case SecurityAlert = 'security_alert';
    case OrderShipped = 'order_shipped';
    case Promotion = 'promotion';

    public function isTransactional(): bool
    {
        return self::Otp === $this || self::SecurityAlert === $this;
    }
}

// in ChannelPicker
public function channelsFor(User $user, NotificationKind $kind): array
{
    if ($kind->isTransactional()) {
        return ['sms', 'email'];      // always: no code, no login
    }

    return $this->prefs->enabledChannels($user, $kind->value);
}

public function send(User $user, string $dedupKey, Notification $n, bool $urgent = false): void
{
    $claimed = $this->db->executeStatement(
        'INSERT INTO notification_log (dedup_key) VALUES (?) ON CONFLICT DO NOTHING',
        [$dedupKey],
    );
    if (0 === $claimed) {
        return;                                    // already sent
    }

    $limit = $this->perUserLimiter->create((string) $user->getId());
    if (!$urgent && !$limit->consume()->isAccepted()) {
        $this->digest->add($user, $n);             // goes out later, together
        return;
    }

    try {
        $this->notifier->send($n, new Recipient($user->getEmail(), $user->getPhone()));
    } catch (\Throwable $e) {
        $this->db->delete('notification_log', ['dedup_key' => $dedupKey]);
        throw $e;                                  // so the retry tries again
    }
}

#[AsPeriodicTask(frequency: '1 hour', schedule: 'default')]
final readonly class SendDigests
{
    public function __construct(
        private DigestRepository $digests,
        private NotifierInterface $notifier,
    ) {}

    public function __invoke(): void
    {
        foreach ($this->digests->usersWithPending() as $user) {
            $items = $this->digests->pendingFor($user);

            $n = (new Notification(count($items).' updates on your orders', ['email']))
                ->content(implode("\n", array_map(fn ($i) => $i->line(), $items)));

            $this->notifier->send($n, new Recipient($user->getEmail()));
            $this->digests->clear($user, $items);   // only after the send worked
        }
    }
}
